package art

import (
	"context"
	"errors"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// TestServiceResolve covers path-serve: the cropped JPEG is served for an
// ingested blob, the verbatim original for a fetch-only PNG blob, the
// malformed-token format guard (table-driven), and the unknown-blob miss
// (404-able os.ErrNotExist).
func TestServiceResolve(t *testing.T) {
	ctx := context.Background()
	svc, _, _ := newTestService(t)

	t.Run("cropped_after_ingest", func(t *testing.T) {
		body := jpegBytes(t, 400, 300)
		srv, _ := newUpstream(t, serveBytes(http.StatusOK, body, 0))
		token, err := svc.Ingest(ctx, "itm_9", "item", srv.URL, "")
		if err != nil {
			t.Fatalf("Ingest: %v", err)
		}
		path, mt, err := svc.Resolve(token)
		if err != nil {
			t.Fatalf("Resolve: %v", err)
		}
		if filepath.Base(path) != croppedFile {
			t.Fatalf("path = %s, want the cropped variant", path)
		}
		if mt != "image/jpeg" {
			t.Fatalf("content type = %s, want image/jpeg", mt)
		}
	})

	t.Run("original_fallback_after_acquire", func(t *testing.T) {
		body := pngBytes(t, 64, 64)
		srv, _ := newUpstream(t, serveBytes(http.StatusOK, body, 0))
		sha, err := svc.Acquire(ctx, srv.URL, "poster")
		if err != nil {
			t.Fatalf("Acquire: %v", err)
		}
		path, mt, err := svc.Resolve("art_" + sha)
		if err != nil {
			t.Fatalf("Resolve: %v", err)
		}
		if filepath.Base(path) != "original.png" {
			t.Fatalf("path = %s, want the verbatim original", path)
		}
		if mt != "image/png" {
			t.Fatalf("content type = %s, want image/png", mt)
		}
		got, err := os.ReadFile(path)
		if err != nil {
			t.Fatalf("read served bytes: %v", err)
		}
		if string(got) != string(body) {
			t.Fatalf("served bytes differ from the upstream body")
		}
	})

	// malformed_tokens: the format guard is the exact art_ + 64-lowercase-hex
	// shape — every deviation is refused before a path is built, so no token
	// can traverse out of the blob tree.
	t.Run("malformed_tokens", func(t *testing.T) {
		hex64 := strings.Repeat("0", 64)
		traversal := "art_" + strings.Repeat("a", 32) + "/" + strings.Repeat("b", 31)
		cases := []struct {
			name  string
			token string
		}{
			{"empty", ""},
			{"prefix_only", "art_"},
			{"wrong_prefix", "blob_" + hex64},
			{"short_hex", "art_" + strings.Repeat("0", 63)},
			{"long_hex", "art_" + strings.Repeat("0", 65)},
			{"uppercase_hex", "art_" + strings.Repeat("A", 64)},
			{"non_hex", "art_" + strings.Repeat("g", 64)},
			{"embedded_separator", traversal},
		}
		for _, tc := range cases {
			t.Run(tc.name, func(t *testing.T) {
				if _, _, err := svc.Resolve(tc.token); err == nil {
					t.Fatalf("Resolve(%q) = nil error, want malformed-token refusal", tc.token)
				}
			})
		}
	})

	t.Run("unknown_blob", func(t *testing.T) {
		_, _, err := svc.Resolve("art_" + strings.Repeat("e", 64))
		if !errors.Is(err, os.ErrNotExist) {
			t.Fatalf("Resolve(unknown) = %v, want os.ErrNotExist (404-able)", err)
		}
	})
}
